package hu.boltseged.shipment;
import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface ShipmentRepository extends JpaRepository<Shipment,UUID>,JpaSpecificationExecutor<Shipment>{Optional<Shipment> findByAccountIdAndIdempotencyKey(UUID accountId,String key);@EntityGraph(attributePaths={"account","packages"})List<Shipment> findByAccountIdOrderByCreatedAtDesc(UUID accountId);@EntityGraph(attributePaths={"account","packages"})@Query("select s from Shipment s where s.account.id=:accountId and s.status='CREATED' and not exists (select 1 from PickupBooking b join b.shipments bookedShipment where b.status='BOOKED' and bookedShipment.id=s.id) order by s.createdAt desc")List<Shipment> findPickupEligibleByAccountId(@Param("accountId")UUID accountId);@EntityGraph(attributePaths={"account","packages"})@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select s from Shipment s where s.id in :ids")List<Shipment> findAllForPickupByIdIn(@Param("ids")Collection<UUID> ids);@EntityGraph(attributePaths={"account","packages"})Optional<Shipment> findDetailedById(UUID id);@Query("select count(s),coalesce(sum(s.dhlEstimatedCost),0),coalesce(sum(s.customerPrice),0),s.currency from Shipment s where s.status='CREATED' and (:a is null or s.account.id=:a) and (:b is null or s.billingStatus=:b) and (:f is null or s.shipDate>=:f) and (:t is null or s.shipDate<=:t) group by s.currency")List<Object[]> summaryByCurrency(@Param("a")UUID accountId,@Param("b")String billingStatus,@Param("f")java.time.LocalDate from,@Param("t")java.time.LocalDate to);}
